import{a as d,c as e,d as l,i as R,j as r,k as L,l as y}from"./chunk-OG55QIAO.js";var i=[{key:"magnitud",label:"Magnitud",align:"left"},{key:"valor",label:"Valor",align:"right",monoespaciado:!0},{key:"errorAbs",label:"Error absoluto",align:"right",monoespaciado:!0},{key:"errorRel",label:"Error relativo",align:"right",monoespaciado:!0}];function A(o,a){return o===0?Number.NaN:a/Math.abs(o)}function t(o,a="",n="x",c="y"){return[y(n,o.x,o.dx,A(o.x,o.dx),a),y(c,o.y,o.dy,A(o.y,o.dy),a),y(`f (${L(o.operacion)})`,o.f,o.errorAbsoluto,o.errorRelativo,a)]}var g=r("producto",12.5,.1,4,.05),x=r("producto",12,.1,.5,.01),$={id:"propagacion-teoria-numerico",titulo:"El \xE1rea de un rect\xE1ngulo de 12,5 \xD7 4,0",tipo:"numerico",planteamiento:"Un rect\xE1ngulo mide 12,5 \xB1 0,1 en un lado y 4,0 \xB1 0,05 en el otro. Se quiere estimar el \xE1rea y la incertidumbre que llega al resultado.",parametros:[{etiqueta:"x",valor:"12,5 \xB1 0,1"},{etiqueta:"y",valor:"4,0 \xB1 0,05"}],interpretacion:"El \xE1rea central es 50. Como es un producto, el error relativo del resultado se aproxima sumando los errores relativos de los factores: 0,008 + 0,0125 = 0,0205, o 2,05 %.",pasos:["\xC1rea central: 12,5 \xB7 4,0 = 50.","Error absoluto: |4,0| \xB7 0,1 + |12,5| \xB7 0,05 = 0,4 + 0,625 = 1,025.","Error relativo: 1,025 / 50 = 0,0205.","Error porcentual: 2,05 %.","Lectura: el \xE1rea queda en 50 \xB1 1,025, aproximadamente."],algoritmo:"Para un producto f = xy, \u0394f \u2248 |y|\u0394x + |x|\u0394y. Es la suma de las contribuciones absolutas de cada factor.",criterio:"La f\xF3rmula es de primer orden: supone errores peque\xF1os frente a los valores. Si los errores son grandes, la linealizaci\xF3n puede quedarse corta.",conclusion:`El \xE1rea es ${e(g.f)} \xB1 ${e(g.errorAbsoluto)}; el error relativo es ${l(g.errorRelativo)}.`,tabla:{columnas:i,filas:t(g)}},j={id:"propagacion-teoria-casuistica",titulo:"La potencia de un circuito: 12 V y 0,50 A",tipo:"casuistica",enunciado:"Una fuente entrega 12,0 \xB1 0,1 V y el circuito consume 0,50 \xB1 0,01 A. Se quiere estimar la potencia P = V\xB7I y su incertidumbre.",planteamiento:"Propagar los errores de tensi\xF3n y corriente al producto P = V\xB7I.",parametros:[{etiqueta:"V",valor:"12,0 \xB1 0,1 V"},{etiqueta:"I",valor:"0,50 \xB1 0,01 A"}],extraccion:{busqueda:"La tensi\xF3n, la corriente y sus errores absolutos.",datos:[{simbolo:"V",valor:"12,0 \xB1 0,1 V",queEs:"tensi\xF3n medidas"},{simbolo:"I",valor:"0,50 \xB1 0,01 A",queEs:"corriente medida"}],formulacion:"P = V\xB7I; \u0394P \u2248 |I|\u0394V + |V|\u0394I."},interpretacion:"La potencia central es 6,0 W. La corriente aporta 0,12 W de incertidumbre y la tensi\xF3n 0,05 W; la suma es 0,17 W, un 2,83 % del resultado.",pasos:["P = 12,0 \xB7 0,50 = 6,0 W.","Contribuci\xF3n de V: |0,50| \xB7 0,1 = 0,05 W.","Contribuci\xF3n de I: |12,0| \xB7 0,01 = 0,12 W.","\u0394P \u2248 0,05 + 0,12 = 0,17 W.","Error relativo: 0,17 / 6,0 \u2248 0,02833, o 2,83 %."],algoritmo:"Se aplica la regla del producto y se conservan las unidades de potencia.",criterio:"La corriente relativa (0,01/0,50 = 2 %) domina frente a la tensi\xF3n relativa (0,1/12 \u2248 0,83 %).",conclusion:`La potencia es ${e(x.f)} \xB1 ${e(x.errorAbsoluto)} W, con un error relativo de ${l(x.errorRelativo)}.`,tabla:{columnas:i,filas:t(x,"W","V","I")}},h={concepto:"Propagar errores es estimar c\xF3mo se transforman las incertidumbres de las entradas cuando se opera con ellas. Si un lado de un rect\xE1ngulo tiene \xB10,1 y el otro \xB10,05, el \xE1rea no tiene el mismo error absoluto: la multiplicaci\xF3n mezcla las dos escalas. La f\xF3rmula de primer orden usa derivadas parciales para pesar cada entrada seg\xFAn cu\xE1nto influye en el resultado.",fundamento:"Para una funci\xF3n f(x, y), una variaci\xF3n peque\xF1a de las entradas se aproxima con la diferencial: df \u2248 (\u2202f/\u2202x)dx + (\u2202f/\u2202y)dy. Como los errores pueden ir en cualquier direcci\xF3n, se toma el peor caso y se suman los valores absolutos: \u0394f \u2248 |f\u2093|\u0394x + |f_y|\u0394y. En un producto, eso se simplifica a la suma de los errores relativos; en una suma, a la suma de los absolutos. La regla no es magia: es la linealizaci\xF3n de la funci\xF3n alrededor del punto de trabajo.",cuandoFalla:"La f\xF3rmula supone errores peque\xF1os y entradas independientes. Si los errores est\xE1n correlacionados, sumar los valores absolutos puede ser demasiado pesimista. En una resta de n\xFAmeros cercanos, el resultado es chico y el error relativo se dispara: hay cancelaci\xF3n. En un cociente, si el denominador se acerca a cero, la derivada explota. Para errores grandes, la linealizaci\xF3n deja de ser confiable y conviene evaluar los extremos o simular.",precision:"La propagaci\xF3n de primer orden es una cota aproximada, no una distribuci\xF3n de probabilidad. Si se conocen las desviaciones est\xE1ndar y las entradas son independientes, la varianza se combina en cuadratura: \u03C3f\xB2 \u2248 \u03A3 (\u2202f/\u2202x\u1D62)\xB2 \u03C3\u1D62\xB2. Este m\xF3dulo trabaja con cotas absolutas y suma de valores absolutos, que es el caso conservador.",recursos:[{titulo:"Propagaci\xF3n de la incertidumbre (Wikipedia, espa\xF1ol)",url:"https://es.wikipedia.org/wiki/Propagaci%C3%B3n_de_la_incertidumbre",tipo:"lectura",descripcion:"La f\xF3rmula general, la combinaci\xF3n en cuadratura y los casos de suma y producto."},{titulo:"N\xFAmero de condici\xF3n (Wikipedia, espa\xF1ol)",url:"https://es.wikipedia.org/wiki/N%C3%BAmero_de_condici%C3%B3n",tipo:"lectura",descripcion:"Por qu\xE9 algunos problemas amplifican el error de entrada y otros lo amortiguan."}],algoritmo:{formula:"\u0394f \u2248 \u03A3\u1D62 |\u2202f/\u2202x\u1D62| \xB7 \u0394x\u1D62",criterios:[{nombre:"Suma o resta",explicacion:"Los errores absolutos se suman: \u0394(x \xB1 y) = \u0394x + \u0394y. La resta no los resta."},{nombre:"Producto o cociente",explicacion:"Los errores relativos se suman: \u0394(xy)/(xy) \u2248 \u0394x/|x| + \u0394y/|y|. Para el cociente, lo mismo."},{nombre:"Tama\xF1o del error",explicacion:"La regla es de primer orden. Con errores grandes hay que comparar con los extremos o simular."}],pasos:["Escribir la funci\xF3n que relaciona el resultado con las entradas.","Identificar las derivadas parciales o la regla particular de la operaci\xF3n.","Multiplicar cada derivada por el error absoluto de su entrada.","Sumar los valores absolutos de las contribuciones.","Dividir por el resultado para obtener el error relativo."],ventajas:["Convierte una pregunta de incertidumbre en una cuenta expl\xEDcita.","Muestra qu\xE9 entrada domina el error del resultado.","Se aplica a sumas, productos, cocientes y funciones m\xE1s generales."],limitaciones:["Es una aproximaci\xF3n de primer orden.","El peor caso puede ser demasiado conservador.","No modela correlaciones entre entradas."],recomendaciones:["Compara las contribuciones relativas para saber d\xF3nde invertir en mejor instrumentaci\xF3n.","No uses la regla si el denominador puede acercarse a cero.","Para errores grandes, verifica con los valores extremos del intervalo."]},ejemploNormal:$,ejemploCasuistica:j},f=r("suma",100,2,220,5),E=r("producto",8,.1,5,.1),q=r("cociente",25,.1,10,.1),C=r("cociente",150,.5,9.7,.1),k=[{id:"propagacion-ejemplo-1",titulo:"Dos resistencias en serie: 100 \xB1 2 y 220 \xB1 5 \u03A9",tipo:"numerico",planteamiento:"Calcular la resistencia equivalente R = R\u2081 + R\u2082 y su error absoluto.",parametros:[{etiqueta:"R\u2081",valor:"100 \xB1 2 \u03A9"},{etiqueta:"R\u2082",valor:"220 \xB1 5 \u03A9"}],interpretacion:"En una suma, los errores absolutos se suman. La resistencia equivalente queda en 320 \u03A9 con una incertidumbre de 7 \u03A9.",pasos:["R = 100 + 220 = 320 \u03A9.","\u0394R = 2 + 5 = 7 \u03A9.","Error relativo: 7/320 \u2248 0,02188.","Error porcentual: 2,19 %."],algoritmo:"Para una suma, \u0394(x+y) = \u0394x + \u0394y.",criterio:"La incertidumbre absoluta se conserva en ohmios; el relativo baja porque la suma es mayor que cada parte.",conclusion:`R = ${e(f.f)} \xB1 ${e(f.errorAbsoluto)} \u03A9; error relativo ${l(f.errorRelativo)}.`,tabla:{columnas:i,filas:t(f,"\u03A9","R\u2081","R\u2082")}},{id:"propagacion-ejemplo-2",titulo:"El \xE1rea de 8,0 \xB1 0,1 por 5,0 \xB1 0,1",tipo:"numerico",planteamiento:"Calcular el \xE1rea y su error absoluto para un producto de dos medidas.",parametros:[{etiqueta:"x",valor:"8,0 \xB1 0,1"},{etiqueta:"y",valor:"5,0 \xB1 0,1"}],interpretacion:"Cada factor aporta su error relativo (1,25 % y 2 %). En un producto, esos porcentajes se suman: 3,25 %.",pasos:["\xC1rea: 8,0 \xB7 5,0 = 40.","\u0394A = 5,0 \xB7 0,1 + 8,0 \xB7 0,1 = 0,5 + 0,8 = 1,3.","Error relativo: 1,3/40 = 0,0325.","Error porcentual: 3,25 %."],algoritmo:"Para un producto, \u0394(xy) \u2248 |y|\u0394x + |x|\u0394y.",criterio:"La suma de errores relativos coincide con el cociente 1,3/40.",conclusion:`El \xE1rea es ${e(E.f)} \xB1 ${e(E.errorAbsoluto)}; error relativo ${l(E.errorRelativo)}.`,tabla:{columnas:i,filas:t(E)}},{id:"propagacion-ejemplo-3",titulo:"Densidad: 25,0 \xB1 0,1 g en 10,0 \xB1 0,1 cm\xB3",tipo:"casuistica",enunciado:"Una muestra tiene masa 25,0 \xB1 0,1 g y volumen 10,0 \xB1 0,1 cm\xB3. Se calcula la densidad y se quiere saber cu\xE1nto pesa cada error en el resultado.",planteamiento:"Calcular \u03C1 = m/V y propagar los errores absolutos de masa y volumen.",parametros:[{etiqueta:"m",valor:"25,0 \xB1 0,1 g"},{etiqueta:"V",valor:"10,0 \xB1 0,1 cm\xB3"}],extraccion:{busqueda:"La masa, el volumen y sus incertidumbres.",datos:[{simbolo:"m",valor:"25,0 \xB1 0,1 g",queEs:"masa"},{simbolo:"V",valor:"10,0 \xB1 0,1 cm\xB3",queEs:"volumen"}],formulacion:"\u03C1 = m/V; \u0394\u03C1 \u2248 \u0394m/|V| + |m|\u0394V/V\xB2."},interpretacion:"La densidad central es 2,5 g/cm\xB3. La masa aporta 0,01 y el volumen 0,025; el volumen pesa m\xE1s porque su error relativo es mayor.",pasos:["\u03C1 = 25,0/10,0 = 2,5 g/cm\xB3.","Contribuci\xF3n de m: 0,1/10,0 = 0,01.","Contribuci\xF3n de V: 25,0 \xB7 0,1 / 100 = 0,025.","\u0394\u03C1 \u2248 0,035 g/cm\xB3.","Error relativo: 1,4 %."],algoritmo:"Para un cociente, \u0394(x/y) \u2248 \u0394x/|y| + |x|\u0394y/y\xB2.",criterio:"La contribuci\xF3n del volumen es 2,5 veces la de la masa; ah\xED est\xE1 la mayor fuente de error.",conclusion:`La densidad es ${e(q.f)} \xB1 ${e(q.errorAbsoluto)} g/cm\xB3; error relativo ${l(q.errorRelativo)}.`,tabla:{columnas:i,filas:t(q,"g/cm\xB3","m","V")}},{id:"propagacion-ejemplo-4",titulo:"Velocidad: 150 \xB1 0,5 m en 9,7 \xB1 0,1 s",tipo:"casuistica",enunciado:"Una medici\xF3n de distancia y tiempo da 150 \xB1 0,5 m y 9,7 \xB1 0,1 s. \xBFCu\xE1l es la velocidad y qu\xE9 incertidumbre tiene?",planteamiento:"Calcular v = d/t y propagar los errores de distancia y tiempo.",parametros:[{etiqueta:"d",valor:"150 \xB1 0,5 m"},{etiqueta:"t",valor:"9,7 \xB1 0,1 s"}],extraccion:{busqueda:"La distancia, el tiempo y sus errores absolutos.",datos:[{simbolo:"d",valor:"150 \xB1 0,5 m",queEs:"distancia"},{simbolo:"t",valor:"9,7 \xB1 0,1 s",queEs:"tiempo"}],formulacion:"v = d/t; \u0394v \u2248 \u0394d/|t| + |d|\u0394t/t\xB2."},interpretacion:"La velocidad central es 15,464 m/s. El tiempo aporta m\xE1s incertidumbre que la distancia porque su error relativo es mayor.",pasos:["v = 150/9,7 \u2248 15,464 m/s.","Contribuci\xF3n de d: 0,5/9,7 \u2248 0,05155.","Contribuci\xF3n de t: 150 \xB7 0,1 / 9,7\xB2 \u2248 0,15942.","\u0394v \u2248 0,21097 m/s.","Error relativo: 1,36 %."],algoritmo:"Regla del cociente con los valores centrales.",criterio:"La incertidumbre del tiempo domina; mejorar el cron\xF3metro reducir\xEDa m\xE1s el error que mejorar la cinta.",conclusion:`La velocidad es ${e(C.f)} \xB1 ${e(C.errorAbsoluto)} m/s; error relativo ${l(C.errorRelativo)}.`,tabla:{columnas:i,filas:t(C,"m/s","d","t")}}];function u(o,a,n,c,v){return{id:o,tipo:"opcion-multiple",enunciado:a,opciones:n,correcta:c,explicacion:v}}var m=r("suma",12.5,.1,7.3,.05),p=r("producto",2.5,.02,4,.05),b=r("cociente",.5,.002,2,.01),T=[{id:"propagacion-ejercicio-1",titulo:"Sumar 12,5 \xB1 0,1 y 7,3 \xB1 0,05",tipo:"numerico",planteamiento:"Calcula el error absoluto del resultado de la suma.",parametros:[{etiqueta:"x",valor:"12,5 \xB1 0,1"},{etiqueta:"y",valor:"7,3 \xB1 0,05"}],interpretacion:"En una suma, los errores absolutos se suman; no se restan.",pasos:["\u0394(x+y) = 0,1 + 0,05.","Resultado: 0,15."],algoritmo:"Regla de la suma: \u0394(x+y) = \u0394x + \u0394y.",criterio:"El resultado central es 19,8 y el error absoluto 0,15.",conclusion:`La suma es ${e(m.f)} \xB1 ${e(m.errorAbsoluto)}.`,tabla:{columnas:i,filas:t(m)},pista:"No importa que sea una suma: los errores absolutos siempre se suman.",cuestionario:[u("propagacion-e1-q1","\xBFC\xF3mo se combinan los errores absolutos en una suma?",[{id:"a",texto:"Se suman."},{id:"b",texto:"Se restan."},{id:"c",texto:"Se multiplican."}],"a","\u0394(x+y) = \u0394x + \u0394y: el peor caso es que ambos se equivoquen hacia el mismo lado."),u("propagacion-e1-q2","\xBFCu\xE1l es el error absoluto de la suma?",[{id:"a",texto:"0,05"},{id:"b",texto:"0,1"},{id:"c",texto:"0,15"}],"c","0,1 + 0,05 = 0,15.")],resolucion:{valorCorrecto:m.errorAbsoluto,tolerancia:1e-9,etiqueta:"Error absoluto de la suma",respuestaFinalTexto:e(m.errorAbsoluto)},formatoRespuesta:"escalar"},{id:"propagacion-ejercicio-2",titulo:"Fuerza: 2,50 \xB1 0,02 kg por 4,00 \xB1 0,05 m/s\xB2",tipo:"numerico",planteamiento:"Calcula la fuerza central F = m\xB7a.",parametros:[{etiqueta:"m",valor:"2,50 \xB1 0,02 kg"},{etiqueta:"a",valor:"4,00 \xB1 0,05 m/s\xB2"}],interpretacion:"El producto de 2,50 por 4,00 da 10,0 N.",pasos:["F = 2,50 \xB7 4,00 = 10,0 N.","El error absoluto se calcula con la regla del producto."],algoritmo:"F = m\xB7a; \u0394F \u2248 |a|\u0394m + |m|\u0394a.",criterio:"La fuerza central es 10,0 N; su error absoluto es 0,205 N.",conclusion:`La fuerza central es ${e(p.f)} N y su error absoluto es ${e(p.errorAbsoluto)} N.`,tabla:{columnas:i,filas:t(p,"N","m","a")},pista:"Primero multiplica los valores centrales; el error se propaga aparte.",cuestionario:[u("propagacion-e2-q1","\xBFCu\xE1l es la fuerza central?",[{id:"a",texto:"6,50 N"},{id:"b",texto:"10,0 N"},{id:"c",texto:"0,205 N"}],"b","2,50 kg \xB7 4,00 m/s\xB2 = 10,0 N."),u("propagacion-e2-q2","\xBFC\xF3mo se calcula el error absoluto de un producto?",[{id:"a",texto:"|a|\u0394m + |m|\u0394a"},{id:"b",texto:"\u0394m + \u0394a"},{id:"c",texto:"\u0394m \xB7 \u0394a"}],"a","Cada error absoluto se multiplica por el otro factor y luego se suman las contribuciones.")],resolucion:{valorCorrecto:p.f,tolerancia:1e-9,etiqueta:"Fuerza central",unidad:"N",respuestaFinalTexto:`${e(p.f)} N`},formatoRespuesta:"escalar"},{id:"propagacion-ejercicio-3",titulo:"Concentraci\xF3n: 0,500 \xB1 0,002 mol en 2,00 \xB1 0,01 L",tipo:"casuistica",enunciado:"Se disuelven 0,500 \xB1 0,002 mol de soluto en 2,00 \xB1 0,01 L de disoluci\xF3n. Calcula la concentraci\xF3n central y su error absoluto.",planteamiento:"Calcular c = n/V y propagar los errores de cantidad y volumen.",parametros:[{etiqueta:"n",valor:"0,500 \xB1 0,002 mol"},{etiqueta:"V",valor:"2,00 \xB1 0,01 L"}],extraccion:{busqueda:"La cantidad de sustancia, el volumen y sus errores.",datos:[{simbolo:"n",valor:"0,500 \xB1 0,002 mol",queEs:"cantidad de soluto"},{simbolo:"V",valor:"2,00 \xB1 0,01 L",queEs:"volumen de disoluci\xF3n"}],formulacion:"c = n/V; \u0394c \u2248 \u0394n/|V| + |n|\u0394V/V\xB2."},interpretacion:"La concentraci\xF3n central es 0,250 mol/L. El volumen aporta 0,00125 y la cantidad 0,001; el volumen domina apenas.",pasos:["c = 0,500/2,00 = 0,250 mol/L.","Contribuci\xF3n de n: 0,002/2,00 = 0,001.","Contribuci\xF3n de V: 0,500 \xB7 0,01 / 4,00 = 0,00125.","\u0394c \u2248 0,00225 mol/L.","Error relativo: 0,9 %."],algoritmo:"Regla del cociente con los valores centrales.",criterio:"La concentraci\xF3n se informa como 0,250 \xB1 0,00225 mol/L; el error relativo es 0,9 %.",conclusion:`c = ${e(b.f)} \xB1 ${e(b.errorAbsoluto)} mol/L.`,tabla:{columnas:i,filas:t(b,"mol/L","n","V")},pista:"En un cociente, el error absoluto combina \u0394n/V y n\xB7\u0394V/V\xB2.",cuestionario:[u("propagacion-e3-q1","\xBFCu\xE1l es la concentraci\xF3n central?",[{id:"a",texto:"0,250 mol/L"},{id:"b",texto:"0,500 mol/L"},{id:"c",texto:"2,00 mol/L"}],"a","0,500 mol / 2,00 L = 0,250 mol/L."),u("propagacion-e3-q2","\xBFQu\xE9 t\xE9rmino corresponde a la contribuci\xF3n del volumen?",[{id:"a",texto:"\u0394n/|V|"},{id:"b",texto:"|n|\u0394V/V\xB2"},{id:"c",texto:"\u0394n + \u0394V"}],"b","La derivada de n/V respecto de V es \u2212n/V\xB2; en valor absoluto, la contribuci\xF3n es n\xB7\u0394V/V\xB2.")],resolucion:{valorCorrecto:b.f,tolerancia:1e-9,etiqueta:"Concentraci\xF3n central",unidad:"mol/L",respuestaFinalTexto:`${e(b.f)} mol/L`},formatoRespuesta:"escalar"}],_=[{key:"operacion",etiqueta:"Operaci\xF3n",ayuda:"Escribe suma, producto o cociente. Tambi\xE9n se aceptan +, \xD7 y \xF7.",requisito:"suma, producto o cociente.",valorInicial:"producto",tipo:"text",placeholder:"producto"},{key:"x",etiqueta:"Valor x",ayuda:"Primer valor central, en las unidades que est\xE9s usando.",requisito:"N\xFAmero finito.",valorInicial:"12.5",tipo:"text",placeholder:"12.5"},{key:"dx",etiqueta:"Error de x",ayuda:"Error absoluto de x. Tiene que ser positivo o cero.",requisito:"N\xFAmero mayor o igual que 0.",valorInicial:"0.1",tipo:"text",placeholder:"0.1"},{key:"y",etiqueta:"Valor y",ayuda:"Segundo valor central. En un cociente, y no puede ser 0.",requisito:"N\xFAmero finito.",valorInicial:"4",tipo:"text",placeholder:"4"},{key:"dy",etiqueta:"Error de y",ayuda:"Error absoluto de y. Tiene que ser positivo o cero.",requisito:"N\xFAmero mayor o igual que 0.",valorInicial:"0.05",tipo:"text",placeholder:"0.05"}];function W(o){let a=R(o.operacion??""),n=d(o.x??""),c=d(o.dx??""),v=d(o.y??""),V=d(o.dy??"");if(!a)return{exito:!1,conclusion:"La operaci\xF3n debe ser suma, producto o cociente."};if(n===null||c===null||v===null||V===null)return{exito:!1,conclusion:"Escribe n\xFAmeros v\xE1lidos para los valores y sus errores."};try{let s=r(a,n,c,v,V),P=Number.isFinite(s.errorRelativo)?`El error relativo del resultado es ${l(s.errorRelativo)}.`:"El error relativo no est\xE1 definido porque el resultado es 0.",N=a==="suma"?"En una suma, los errores absolutos se suman.":a==="producto"?"En un producto, los errores relativos se suman aproximadamente.":"En un cociente, los errores relativos se suman aproximadamente.";return{exito:!0,resultado:e(s.f,10),etiquetaResultado:`Resultado de la ${L(a)}`,detalle:e(s.errorAbsoluto,10),etiquetaDetalle:"Error absoluto",conclusion:`${N} ${P}`,filas:t(s),columnas:i}}catch(s){return{exito:!1,conclusion:s instanceof Error?s.message:"No se pudo propagar el error."}}}export{i as a,h as b,k as c,T as d,_ as e,W as f};
